 static void Begin(Dictionary<string,object> m){Identity(m);height=(int)N(m,"height");session=S(m,"session");sourceHeight=(int)N(m,"sourceHeight");selectedTag=(int)N(m,"itag");selectedCodec=S(m,"codec").ToLowerInvariant();if(selectedCodec=="auto")selectedCodec="";string list=S(m,"tagList");if(list.Length>0){if(list.Length>256)throw new Exception("Список форматов слишком длинный.");List<int> tags=new List<int>();foreach(string item in list.Split(',')){int tag;if(!Int32.TryParse(item,out tag)||tag<1||tag>10000)throw new Exception("Неверный формат в списке.");if(!tags.Contains(tag))tags.Add(tag);}allowedTags=tags.ToArray();}if(sourceHeight<0||sourceHeight>8192||selectedTag<0||selectedTag>10000||(selectedCodec!=""&&selectedCodec!="h264"&&selectedCodec!="vp9"&&selectedCodec!="av1"))throw new Exception("Неверный формат.");if((height!=144&&height!=240&&height!=360&&height!=480&&height!=720&&height!=1080)||!Regex.IsMatch(session,@"^[A-Za-z0-9_-]{15,90}$"))throw new Exception("Неверные параметры захвата.");folder=Path.Combine(Path.Combine(data,"CAPTURE_TEMP"),session);Directory.CreateDirectory(folder);cached=HasAudio();Send(new {action="ready",ok=true,audioCached=cached,message=cached?"Звук уже в кэше":"Захват готов"});}
 static string Key(Dictionary<string,object> m){return N(m,"itag")+"_"+(B(m,"init")?"i":"s")+"_"+N(m,"segment")+"_"+N(m,"request")+"_"+N(m,"headerId");}
 static void Record(Dictionary<string,object> m,string action){if(S(m,"session")!=session)throw new Exception("Сессия не совпадает.");int tag=(int)N(m,"itag"),seq=(int)N(m,"segment"),req=(int)N(m,"request");if(tag<1||tag>10000||seq< -1||seq>1000000||req<1||req>100000)throw new Exception("Неверный сегмент.");if(cached&&(tag==139||tag==140||tag==249||tag==250||tag==251))return;string key=Key(m);Rec r;if(!records.TryGetValue(key,out r)){if(action!="header")throw new Exception("Данные пришли до заголовка сегмента.");r=new Rec();r.itag=tag;r.seq=seq;r.req=req;r.init=B(m,"init");r.start=N(m,"start");r.duration=N(m,"duration");r.length=N(m,"length");r.offset=N(m,"offset");if(r.offset<0)throw new Exception("Неверное смещение сегмента.");r.path=Path.Combine(folder,key+".bin");records[key]=r;return;}if(action=="chunk"){if(r.done)throw new Exception("Данные после окончания сегмента.");byte[] b=Convert.FromBase64String(S(m,"data"));if(b.Length>12500)throw new Exception("Слишком большой фрагмент.");total+=b.Length;if(total>16L*1024*1024*1024)throw new Exception("Достигнут лимит 16 ГБ.");if(r.stream==null)r.stream=new FileStream(r.path,FileMode.Create,FileAccess.Write);r.stream.Write(b,0,b.Length);}else if(action=="end"){if(r.stream!=null){r.stream.Close();r.stream=null;}r.done=File.Exists(r.path)&&new FileInfo(r.path).Length>0&&(r.length<=0||r.offset+new FileInfo(r.path).Length<=r.length);if(r.init&&r.done)CheckInit(tag);}}
