  foreach(KeyValuePair<int,List<Rec>> kv in segs){Rec r=kv.Value[0];if(last<0&&r.start>150)throw new Exception("Отсутствует начало ролика.");if(last>=0&&(kv.Key!=last+1||r.start>end+100))throw new Exception("Пропуск сегментов в потоке "+tag+".");if(r.duration<=0)throw new Exception("Неизвестна длительность сегмента.");end=r.start+r.duration;last=kv.Key;}
