 static void RequestEnd(Dictionary<string,object> m){if(S(m,"session")!=session)throw new Exception("Сессия не совпадает.");long req=N(m,"request");foreach(Rec r in records.Values)if(r.req==req){if(r.stream!=null){r.stream.Close();r.stream=null;}if(File.Exists(r.path)){long size=new FileInfo(r.path).Length;r.done=size>0&&(r.length<=0||r.offset+size<=r.length);if(r.init&&r.done)CheckInit(r.itag);}}}
