 static string Decode(Dictionary<string,object> m,string key){return Encoding.UTF8.GetString(Convert.FromBase64String(S(m,key)));}
 static void StreamMP3(Dictionary<string,object> begin){
  Identity(begin);folder=Path.Combine(Path.Combine(data,"MEDIA_TEMP"),Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string source=Path.Combine(folder,"source.mp4");long bytes=0;bool complete=false;
