 static void Media(Dictionary<string,object> m,string action){Identity(m);if(action=="lookup"){Send(new {action="result",ok=true,cached=HasAudio(),audioCodec=HasAudio()&&Regex.IsMatch(Run("-i "+Q(Audio()),false),@"Audio:\s*aac\b")?"aac":"other"});return;}if(action=="import"){string path=Path.GetFullPath(Decode(m,"input"));if(!File.Exists(path)||!path.EndsWith(".mp4",StringComparison.OrdinalIgnoreCase))throw new Exception("Исходный MP4 отсутствует.");Verify(path,false);CacheAudio(path);Send(new {action="result",ok=true,message="Звук из 360p сохранён в локальный кэш."});return;}if(action=="aac"){if(!HasAudio()||!Regex.IsMatch(Run("-i "+Q(Audio()),false),@"Audio:\s*aac\b"))throw new Exception("В кэше нет исходного AAC из 360p.");Directory.CreateDirectory(Path.Combine(data,"MEDIA_TEMP"));string destAAC=Destination("AAC original",".m4a"),tempAAC=Path.Combine(Path.Combine(data,"MEDIA_TEMP"),Guid.NewGuid().ToString("N")+".m4a");try{Status(90,"Извлекаю AAC без перекодирования…");Run("-loglevel error -y -i "+Q(Audio())+" -map 0:a:0 -vn -c:a copy -movflags +faststart -f mp4 "+Q(tempAAC),true);Verify(tempAAC,false);File.Move(tempAAC,destAAC);Result(destAAC);}finally{if(File.Exists(tempAAC))File.Delete(tempAAC);}return;}if(action!="mp3")throw new Exception("Неизвестная команда.");if(!HasAudio())throw new Exception("Звук ещё не сохранён. Используйте загрузку MP3 через браузер.");else Status(82,"Использую уже сохранённый звук — без повторной загрузки.");string dest=Destination("MP3 320",".mp3");Directory.CreateDirectory(Path.Combine(data,"MEDIA_TEMP"));string temp=Path.Combine(Path.Combine(data,"MEDIA_TEMP"),Guid.NewGuid().ToString("N")+".mp3");try{Status(90,"Создаю MP3 320 кбит/с…");Run("-loglevel error -y -i "+Q(Audio())+" -vn -c:a libmp3lame -b:a 320k -ar 44100 "+Q(temp),true);if(new FileInfo(temp).Length<1000)throw new Exception("MP3 пуст.");File.Move(temp,dest);Result(dest);}finally{if(File.Exists(temp))File.Delete(temp);}}

 static void BackgroundReceive(Dictionary<string,object> begin){
  Identity(begin);height=(int)N(begin,"height");sourceHeight=(int)N(begin,"sourceHeight");selectedCodec=S(begin,"codec").ToLowerInvariant();if((height!=144&&height!=240&&height!=360&&height!=480&&height!=720&&height!=1080)||sourceHeight<1||sourceHeight>8192||(selectedCodec!="h264"&&selectedCodec!="vp9"&&selectedCodec!="av1"))throw new Exception("Неверный фоновый формат.");
