 static int Main(string[] args){try{if(args.Length==1&&args[0]=="--version"){Console.WriteLine("YouTube Downloader 2.5.0; target CLR 2; x86");return 0;}if(args.Length==2&&args[0]=="--test-root"){data=Path.GetFullPath(args[1]);testDesktop=Path.Combine(data,"RESULTS");}if(!File.Exists(ff))throw new Exception("FFmpeg отсутствует.");Dictionary<string,object> m=Read();if(m==null)return 0;string action=S(m,"action");if(action=="backgroundStart"){BackgroundReceive(m);return 0;}if(action=="mp3stream"||action=="aacstream"){StreamMP3(m);return 0;}if(action!="start"){Media(m,action);return 0;}Begin(m);while((m=Read())!=null){action=S(m,"action");if(action=="header"||action=="chunk"||action=="end")Record(m,action);else if(action=="requestEnd")RequestEnd(m);else if(action=="finish"){Finish();return 0;}else if(action=="cancel")return 0;else if(action=="ping")Send(new {action="pong"});else throw new Exception("Неизвестная команда.");}return 0;}catch(Exception e){try{Send(new {action="result",ok=false,error=e.Message});}catch{}return 1;}finally{Cleanup();}}
